USE [JamunaBankProcurement];
GO
CREATE TABLE dbo.REQUISITION_HEADER (
 REQUISITION_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REQUISITION_HEADER PRIMARY KEY,
 REQUISITION_NO VARCHAR(30) NOT NULL CONSTRAINT UQ_REQUISITION_NO UNIQUE,
 REQUESTED_BY_EMPLOYEE_ID VARCHAR(30) NOT NULL, REQUESTED_ORG_UNIT_ID BIGINT NOT NULL,
 REQUESTED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REQ_REQUESTED_DATE DEFAULT SYSUTCDATETIME(), JUSTIFICATION NVARCHAR(2000) NOT NULL,
 TOTAL_ESTIMATED_AMOUNT DECIMAL(18,2) NOT NULL CONSTRAINT DF_REQ_TOTAL DEFAULT(0), CURRENT_STATUS VARCHAR(40) NOT NULL CONSTRAINT DF_REQ_STATUS DEFAULT('DRAFT'),
 CREATED_BY VARCHAR(50) NOT NULL, CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REQ_CREATED DEFAULT SYSUTCDATETIME(), MODIFIED_BY VARCHAR(50) NULL, MODIFIED_DATE DATETIME2(3) NULL,
 IS_ACTIVE BIT NOT NULL CONSTRAINT DF_REQ_ACTIVE DEFAULT(1), ROW_VERSION ROWVERSION NOT NULL,
 CONSTRAINT FK_REQ_EMP FOREIGN KEY(REQUESTED_BY_EMPLOYEE_ID) REFERENCES dbo.APP_USER_CACHE(EMPLOYEE_ID),
 CONSTRAINT FK_REQ_ORG FOREIGN KEY(REQUESTED_ORG_UNIT_ID) REFERENCES dbo.ORG_UNIT(ORG_UNIT_ID),
 CONSTRAINT CK_REQ_TOTAL CHECK(TOTAL_ESTIMATED_AMOUNT>=0),
 CONSTRAINT CK_REQ_STATUS CHECK(CURRENT_STATUS IN ('DRAFT','SUBMITTED','MANAGER_RETURNED','MANAGER_REJECTED','IN_WORKFLOW','RETURNED','REJECTED','NOT_RECOMMENDED','READY_FOR_PROCUREMENT','PROCUREMENT_IN_PROGRESS','COMPLETED'))
);

CREATE TABLE dbo.REQUISITION_ITEM (
 REQ_ITEM_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REQUISITION_ITEM PRIMARY KEY,
 REQUISITION_ID BIGINT NOT NULL, ASSET_ID BIGINT NOT NULL, ITEM_NAME_SNAPSHOT NVARCHAR(200) NOT NULL,
 REQ_TYPE VARCHAR(20) NOT NULL, QUANTITY DECIMAL(18,2) NOT NULL, ESTIMATED_UNIT_PRICE DECIMAL(18,2) NOT NULL,
 ESTIMATED_TOTAL_PRICE AS CONVERT(DECIMAL(18,2),QUANTITY*ESTIMATED_UNIT_PRICE) PERSISTED,
 PURPOSE_JUSTIFICATION NVARCHAR(2000) NOT NULL, ADDITIONAL_SPEC_REQUIREMENT NVARCHAR(2000) NULL,
 IS_ACTIVE BIT NOT NULL CONSTRAINT DF_REQ_ITEM_ACTIVE DEFAULT(1), CREATED_BY VARCHAR(50) NOT NULL,
 CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REQ_ITEM_CREATED DEFAULT SYSUTCDATETIME(), MODIFIED_BY VARCHAR(50) NULL, MODIFIED_DATE DATETIME2(3) NULL,
 CONSTRAINT FK_REQ_ITEM_HEADER FOREIGN KEY(REQUISITION_ID) REFERENCES dbo.REQUISITION_HEADER(REQUISITION_ID),
 CONSTRAINT FK_REQ_ITEM_ASSET FOREIGN KEY(ASSET_ID) REFERENCES dbo.ASSET_MASTER(ASSET_ID),
 CONSTRAINT CK_REQ_ITEM_TYPE CHECK(REQ_TYPE IN ('NEW','REPLACEMENT','ADDITIONAL')), CONSTRAINT CK_REQ_ITEM_QTY CHECK(QUANTITY>0), CONSTRAINT CK_REQ_ITEM_PRICE CHECK(ESTIMATED_UNIT_PRICE>=0)
);

CREATE TABLE dbo.REQUISITION_REPLACEMENT_INFO (
 REPLACEMENT_INFO_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REPLACEMENT_INFO PRIMARY KEY,
 REQ_ITEM_ID BIGINT NOT NULL CONSTRAINT UQ_REPLACEMENT_ITEM UNIQUE, ASSET_TAG_NO NVARCHAR(100) NULL, SERIAL_NO NVARCHAR(100) NULL,
 CURRENT_CONDITION NVARCHAR(2000) NOT NULL, ADDITIONAL_INFO NVARCHAR(2000) NULL, CREATED_BY VARCHAR(50) NOT NULL,
 CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REPLACE_CREATED DEFAULT SYSUTCDATETIME(), MODIFIED_BY VARCHAR(50) NULL, MODIFIED_DATE DATETIME2(3) NULL,
 CONSTRAINT FK_REPLACE_ITEM FOREIGN KEY(REQ_ITEM_ID) REFERENCES dbo.REQUISITION_ITEM(REQ_ITEM_ID)
);

CREATE TABLE dbo.REQUISITION_ITEM_SPEC (
 REQ_ITEM_SPEC_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REQ_ITEM_SPEC PRIMARY KEY,
 REQ_ITEM_ID BIGINT NOT NULL, ASSET_SPEC_ID BIGINT NOT NULL, SPEC_NAME_SNAPSHOT NVARCHAR(150) NOT NULL, SPEC_TYPE_SNAPSHOT VARCHAR(20) NOT NULL,
 SPEC_TEXT_VALUE NVARCHAR(1000) NULL, SPEC_NUM_VALUE DECIMAL(18,4) NULL, SPEC_DATE_VALUE DATE NULL, SPEC_BOOL_VALUE BIT NULL,
 IS_MANDATORY_SNAPSHOT BIT NOT NULL, DISPLAY_ORDER_SNAPSHOT INT NOT NULL, CREATED_BY VARCHAR(50) NOT NULL,
 CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REQ_SPEC_CREATED DEFAULT SYSUTCDATETIME(), MODIFIED_BY VARCHAR(50) NULL, MODIFIED_DATE DATETIME2(3) NULL,
 CONSTRAINT FK_REQ_SPEC_ITEM FOREIGN KEY(REQ_ITEM_ID) REFERENCES dbo.REQUISITION_ITEM(REQ_ITEM_ID), CONSTRAINT FK_REQ_SPEC_DEF FOREIGN KEY(ASSET_SPEC_ID) REFERENCES dbo.ASSET_SPEC_DEFINITION(ASSET_SPEC_ID),
 CONSTRAINT UQ_REQ_ITEM_SPEC UNIQUE(REQ_ITEM_ID,ASSET_SPEC_ID), CONSTRAINT CK_REQ_SPEC_TYPE CHECK(SPEC_TYPE_SNAPSHOT IN ('TEXT','NUMBER','DATE','DROPDOWN','MULTI_SELECT','YES_NO')),
 CONSTRAINT CK_REQ_SPEC_ONE_VALUE CHECK((CASE WHEN SPEC_TEXT_VALUE IS NULL THEN 0 ELSE 1 END + CASE WHEN SPEC_NUM_VALUE IS NULL THEN 0 ELSE 1 END + CASE WHEN SPEC_DATE_VALUE IS NULL THEN 0 ELSE 1 END + CASE WHEN SPEC_BOOL_VALUE IS NULL THEN 0 ELSE 1 END)<=1)
);

CREATE TABLE dbo.REQUISITION_ITEM_SPEC_OPTION (
 REQ_ITEM_SPEC_OPTION_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REQ_SPEC_OPTION PRIMARY KEY,
 REQ_ITEM_SPEC_ID BIGINT NOT NULL, ASSET_SPEC_OPTION_ID BIGINT NOT NULL, SELECTED_OPTION_TEXT_SNAPSHOT NVARCHAR(300) NOT NULL,
 CREATED_BY VARCHAR(50) NOT NULL, CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_REQ_SPEC_OPTION_CREATED DEFAULT SYSUTCDATETIME(),
 CONSTRAINT FK_REQ_SPEC_OPTION_REQ FOREIGN KEY(REQ_ITEM_SPEC_ID) REFERENCES dbo.REQUISITION_ITEM_SPEC(REQ_ITEM_SPEC_ID),
 CONSTRAINT FK_REQ_SPEC_OPTION_MASTER FOREIGN KEY(ASSET_SPEC_OPTION_ID) REFERENCES dbo.ASSET_SPEC_OPTION(ASSET_SPEC_OPTION_ID),
 CONSTRAINT UQ_REQ_SPEC_OPTION UNIQUE(REQ_ITEM_SPEC_ID,ASSET_SPEC_OPTION_ID)
);

CREATE TABLE dbo.WORKFLOW_INSTANCE (
 WORKFLOW_INSTANCE_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_WORKFLOW_INSTANCE PRIMARY KEY,
 REQUISITION_ID BIGINT NOT NULL, WORKFLOW_RULE_ID BIGINT NULL, CURRENT_STAGE VARCHAR(40) NOT NULL, CURRENT_OWNER_TYPE VARCHAR(30) NOT NULL,
 CURRENT_OWNER_EMPLOYEE_ID VARCHAR(30) NULL, CURRENT_OWNER_ORG_UNIT_ID BIGINT NULL, CURRENT_STATUS VARCHAR(30) NOT NULL,
 STARTED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_WFI_STARTED DEFAULT SYSUTCDATETIME(), COMPLETED_DATE DATETIME2(3) NULL,
 CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_WFI_CREATED DEFAULT SYSUTCDATETIME(), MODIFIED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_WFI_MODIFIED DEFAULT SYSUTCDATETIME(), ROW_VERSION ROWVERSION NOT NULL,
 CONSTRAINT FK_WFI_REQ FOREIGN KEY(REQUISITION_ID) REFERENCES dbo.REQUISITION_HEADER(REQUISITION_ID), CONSTRAINT FK_WFI_RULE FOREIGN KEY(WORKFLOW_RULE_ID) REFERENCES dbo.WORKFLOW_RULE(WORKFLOW_RULE_ID),
 CONSTRAINT FK_WFI_EMP FOREIGN KEY(CURRENT_OWNER_EMPLOYEE_ID) REFERENCES dbo.APP_USER_CACHE(EMPLOYEE_ID), CONSTRAINT FK_WFI_ORG FOREIGN KEY(CURRENT_OWNER_ORG_UNIT_ID) REFERENCES dbo.ORG_UNIT(ORG_UNIT_ID),
 CONSTRAINT CK_WFI_OWNER CHECK((CURRENT_OWNER_TYPE='EMPLOYEE' AND CURRENT_OWNER_EMPLOYEE_ID IS NOT NULL) OR (CURRENT_OWNER_TYPE='ORG_UNIT' AND CURRENT_OWNER_ORG_UNIT_ID IS NOT NULL) OR CURRENT_OWNER_TYPE IN ('ROLE_POOL','NONE')),
 CONSTRAINT CK_WFI_STATUS CHECK(CURRENT_STATUS IN ('PENDING','TAKEN','COMPLETED','RETURNED','REJECTED'))
);

CREATE TABLE dbo.REQUISITION_ASSIGNMENT (
 ASSIGNMENT_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REQ_ASSIGNMENT PRIMARY KEY,
 REQUISITION_ID BIGINT NOT NULL, ASSIGNMENT_TYPE VARCHAR(40) NOT NULL, ASSIGNED_TO_EMPLOYEE_ID VARCHAR(30) NULL, ASSIGNED_TO_ORG_UNIT_ID BIGINT NULL,
 ASSIGNED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_ASSIGN_DATE DEFAULT SYSUTCDATETIME(), RELEASED_DATE DATETIME2(3) NULL, DUE_DATE DATETIME2(3) NULL,
 IS_CURRENT BIT NOT NULL CONSTRAINT DF_ASSIGN_CURRENT DEFAULT(1), CREATED_BY VARCHAR(50) NOT NULL, CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_ASSIGN_CREATED DEFAULT SYSUTCDATETIME(),
 CONSTRAINT FK_ASSIGN_REQ FOREIGN KEY(REQUISITION_ID) REFERENCES dbo.REQUISITION_HEADER(REQUISITION_ID), CONSTRAINT FK_ASSIGN_EMP FOREIGN KEY(ASSIGNED_TO_EMPLOYEE_ID) REFERENCES dbo.APP_USER_CACHE(EMPLOYEE_ID),
 CONSTRAINT FK_ASSIGN_ORG FOREIGN KEY(ASSIGNED_TO_ORG_UNIT_ID) REFERENCES dbo.ORG_UNIT(ORG_UNIT_ID), CONSTRAINT CK_ASSIGN_TARGET CHECK(ASSIGNED_TO_EMPLOYEE_ID IS NOT NULL OR ASSIGNED_TO_ORG_UNIT_ID IS NOT NULL OR ASSIGNMENT_TYPE IN ('PROCUREMENT_AUTHORITY_POOL','PROCUREMENT_OFFICER_POOL')),
 CONSTRAINT CK_ASSIGN_RELEASE CHECK((IS_CURRENT=1 AND RELEASED_DATE IS NULL) OR (IS_CURRENT=0 AND RELEASED_DATE IS NOT NULL))
);

CREATE TABLE dbo.APPROVAL_ACTION (
 APPROVAL_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_APPROVAL_ACTION PRIMARY KEY,
 REQUISITION_ID BIGINT NOT NULL, REQ_ITEM_ID BIGINT NULL, ACTION_TYPE VARCHAR(50) NOT NULL, ACTION_BY_EMPLOYEE_ID VARCHAR(30) NOT NULL,
 ACTION_ROLE VARCHAR(40) NOT NULL, FROM_STAGE VARCHAR(40) NULL, TO_STAGE VARCHAR(40) NULL, ACTION_DATETIME DATETIME2(3) NOT NULL CONSTRAINT DF_APPROVAL_DATE DEFAULT SYSUTCDATETIME(),
 REMARKS NVARCHAR(2000) NULL, BATCH_REFERENCE_ID UNIQUEIDENTIFIER NULL, CREATED_DATE DATETIME2(3) NOT NULL CONSTRAINT DF_APPROVAL_CREATED DEFAULT SYSUTCDATETIME(),
 CONSTRAINT FK_APPROVAL_REQ FOREIGN KEY(REQUISITION_ID) REFERENCES dbo.REQUISITION_HEADER(REQUISITION_ID), CONSTRAINT FK_APPROVAL_ITEM FOREIGN KEY(REQ_ITEM_ID) REFERENCES dbo.REQUISITION_ITEM(REQ_ITEM_ID),
 CONSTRAINT FK_APPROVAL_EMP FOREIGN KEY(ACTION_BY_EMPLOYEE_ID) REFERENCES dbo.APP_USER_CACHE(EMPLOYEE_ID),
 CONSTRAINT CK_APPROVAL_ACTION CHECK(ACTION_TYPE IN ('SUBMIT','MANAGER_APPROVE','MANAGER_RETURN','MANAGER_REJECT','PROCUREMENT_OFFICER_TAKE','PROCUREMENT_OFFICER_APPROVE','PROCUREMENT_OFFICER_RETURN','PROCUREMENT_OFFICER_REJECT','PROCUREMENT_AUTHORITY_APPROVE','PROCUREMENT_AUTHORITY_REJECT','PROCUREMENT_AUTHORITY_FORWARD','CONCERN_VERIFY_COMPLETE','CONCERN_FORWARD_TO_AUTHORITY','CONCERN_RETURN','CONCERN_NOT_RECOMMEND','CONCERN_AUTHORITY_APPROVE','CONCERN_AUTHORITY_RETURN','CONCERN_AUTHORITY_REJECT'))
);

CREATE TABLE dbo.WORKFLOW_HISTORY (
 WORKFLOW_HISTORY_ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_WORKFLOW_HISTORY PRIMARY KEY,
 REQUISITION_ID BIGINT NOT NULL, WORKFLOW_RULE_ID BIGINT NULL, FROM_STAGE VARCHAR(40) NULL, TO_STAGE VARCHAR(40) NOT NULL,
 ACTION_TYPE VARCHAR(50) NOT NULL, ACTION_BY_EMPLOYEE_ID VARCHAR(30) NOT NULL, ACTION_DATETIME DATETIME2(3) NOT NULL CONSTRAINT DF_WFH_DATE DEFAULT SYSUTCDATETIME(),
 REMARKS NVARCHAR(2000) NULL, BATCH_REFERENCE_ID UNIQUEIDENTIFIER NULL,
 CONSTRAINT FK_WFH_REQ FOREIGN KEY(REQUISITION_ID) REFERENCES dbo.REQUISITION_HEADER(REQUISITION_ID), CONSTRAINT FK_WFH_RULE FOREIGN KEY(WORKFLOW_RULE_ID) REFERENCES dbo.WORKFLOW_RULE(WORKFLOW_RULE_ID),
 CONSTRAINT FK_WFH_EMP FOREIGN KEY(ACTION_BY_EMPLOYEE_ID) REFERENCES dbo.APP_USER_CACHE(EMPLOYEE_ID)
);
GO
